package com.skyward.api;
import com.skyward.api.ApiDtos.*;
import com.skyward.security.AppPrincipal;
import com.skyward.entity.UserEntity;
import com.skyward.repository.UserRepository;
import com.skyward.service.BookingService;
import jakarta.validation.Valid;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.crypto.password.PasswordEncoder;
import java.math.BigDecimal;
import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.*;
@RestController @RequestMapping("/api/admin")
public class AdminController {
 private final JdbcTemplate db;private final BookingService bookings;private final PasswordEncoder passwords;private final UserRepository users;public AdminController(JdbcTemplate db,BookingService bookings,PasswordEncoder passwords,UserRepository users){this.db=db;this.bookings=bookings;this.passwords=passwords;this.users=users;}
 @GetMapping("/users") public List<Map<String,Object>> searchUsers(@RequestParam(defaultValue="")String q){String term=q.trim();return users.findTop50ByNameContainingIgnoreCaseOrEmailContainingIgnoreCaseOrderByNameAsc(term,term).stream().map(u->{Map<String,Object>m=new LinkedHashMap<>();m.put("userId",u.getId());m.put("name",u.getName());m.put("email",u.getEmail());m.put("phone",u.getPhone());return m;}).toList();}
 @GetMapping("/users/{id}") public Map<String,Object> user(@PathVariable long id){UserEntity u=users.findById(id).orElseThrow(()->new IllegalArgumentException("Passenger account was not found."));Map<String,Object> profile=new LinkedHashMap<>();profile.put("userId",u.getId());profile.put("name",u.getName());profile.put("email",u.getEmail());profile.put("phone",u.getPhone());profile.put("createdAt",u.getCreatedAt());List<Map<String,Object>> history=db.queryForList("SELECT b.booking_id bookingId,b.status,b.total_amount totalAmount,b.booking_date bookingDate,f.flight_number flightNumber,f.departure_city departureCity,f.destination_city destinationCity,f.departure_time departureTime,(SELECT r.request_status FROM cancellation_requests r WHERE r.booking_id=b.booking_id ORDER BY r.request_id DESC LIMIT 1) cancellationStatus FROM bookings b JOIN flights f ON f.flight_id=b.flight_id WHERE b.user_id=? ORDER BY b.booking_date DESC",id);return Map.of("profile",profile,"bookings",history,"boardingPasses",bookings.boardingPasses(id));}
 @PostMapping("/users/{id}/reset-password") public Map<String,String> resetUserPassword(@PathVariable long id,@Valid @RequestBody AdminPasswordReset r){if(!r.newPassword().equals(r.confirmPassword()))throw new IllegalArgumentException("Passwords do not match.");UserEntity u=users.findById(id).orElseThrow(()->new IllegalArgumentException("Passenger account was not found."));u.setPasswordHash(passwords.encode(r.newPassword()));users.save(u);return Map.of("message","Passenger password reset successfully.");}
 @GetMapping("/bookings") public List<Map<String,Object>> allBookings(){return db.queryForList("SELECT b.booking_id bookingId,b.status,b.total_amount totalAmount,b.booking_date bookingDate,u.name,u.email,f.flight_number flightNumber,f.departure_city departureCity,f.destination_city destinationCity,f.departure_time departureTime FROM bookings b JOIN users u ON u.user_id=b.user_id JOIN flights f ON f.flight_id=b.flight_id ORDER BY b.booking_date DESC");}
 @DeleteMapping("/bookings/{id}") public Map<String,String> deleteBooking(@PathVariable long id){bookings.deleteBookingForAdmin(id);return Map.of("message","Booking deleted.");}
 @GetMapping("/cancellation-requests") public List<Map<String,Object>> cancellations(){return db.queryForList("SELECT r.request_id requestId,r.booking_id bookingId,r.user_id userId,r.request_date requestDate,r.request_status requestStatus,u.name,u.email,f.flight_number flightNumber,f.departure_city departureCity,f.destination_city destinationCity,f.departure_time departureTime FROM cancellation_requests r JOIN users u ON u.user_id=r.user_id JOIN bookings b ON b.booking_id=r.booking_id JOIN flights f ON f.flight_id=b.flight_id ORDER BY CASE r.request_status WHEN 'PENDING' THEN 0 ELSE 1 END,r.request_date DESC");}
 @PostMapping("/cancellation-requests/{id}/resolve") public Map<String,Object> resolve(@PathVariable long id,@RequestBody ResolveCancellation body,Authentication auth){return bookings.resolveCancellation(id,body.approve(),((AppPrincipal)auth.getPrincipal()).id(),body.response());}
 @GetMapping("/flights") public List<Map<String,Object>> flights(){return db.queryForList("SELECT f.*,a.airline_name airlineName FROM flights f JOIN airlines a ON a.airline_id=f.airline_id ORDER BY f.departure_time");}
 @GetMapping("/flights/{flightId}/manifest") public List<Map<String,Object>> passengerManifest(@PathVariable long flightId){return db.queryForList("SELECT b.booking_id bookingId,p.name,p.age,p.gender,p.verification_id_type verificationIdType,p.verification_id_number verificationIdNumber,t.seat_number seatNumber,t.cabin_class cabinClass FROM bookings b JOIN passengers p ON p.booking_id=b.booking_id JOIN tickets t ON t.booking_id=b.booking_id AND t.passenger_id=p.passenger_id WHERE b.flight_id=? AND b.status IN ('PENDING','CONFIRMED') AND t.ticket_status='ISSUED' ORDER BY t.cabin_class,t.seat_number,p.name",flightId);}
 @Transactional @PostMapping("/flights") public Map<String,Object> addFlight(@Valid @RequestBody CreateFlight f){return saveFlight(0,f);}
 @Transactional @PutMapping("/flights/{id}") public Map<String,Object> updateFlight(@PathVariable long id,@Valid @RequestBody CreateFlight f){return saveFlight(id,f);}
 @Transactional @DeleteMapping("/flights/{id}") public Map<String,String> deleteFlight(@PathVariable long id){db.update("DELETE FROM flights WHERE flight_id=?",id);return Map.of("message","Flight deleted.");}
 private Map<String,Object> saveFlight(long id,CreateFlight f){
  LocalDateTime dep=LocalDateTime.parse(f.departureTime()),arr=LocalDateTime.parse(f.arrivalTime());int totalCapacity=f.economyCapacity()+f.businessCapacity();if(!arr.isAfter(dep)||f.departureCity().equalsIgnoreCase(f.destinationCity()))throw new IllegalArgumentException("Check the route and flight times.");if(totalCapacity<=0||f.businessCapacity()<6||f.businessCapacity()%6!=0||f.businessCapacity()<totalCapacity*.25||f.businessCapacity()>totalCapacity*.40)throw new IllegalArgumentException("Use a positive cabin capacity with Business Class near one-third of total seats and in whole six-seat rows.");
  if(f.economyPrice()==null||f.businessPrice()==null||f.businessPrice().compareTo(f.economyPrice().multiply(new BigDecimal("2.5")))<0||f.businessPrice().compareTo(f.economyPrice().multiply(new BigDecimal("3.0")))>0)throw new IllegalArgumentException("Business fare must be between 2.5× and 3× Economy fare.");
  int ecoTaken=0,bizTaken=0;if(id>0){Map<String,Object> current=db.queryForMap("SELECT economy_capacity,business_capacity FROM flights WHERE flight_id=? FOR UPDATE",id);List<Map<String,Object>> counts=db.queryForList("SELECT cabin_class,COUNT(DISTINCT TRIM(UPPER(t.seat_number))) n FROM tickets t JOIN bookings b ON b.booking_id=t.booking_id WHERE t.flight_id=? AND t.ticket_status='ISSUED' AND b.status IN ('PENDING','CONFIRMED') GROUP BY cabin_class",id);for(var row:counts){if("BUSINESS".equals(row.get("cabin_class")))bizTaken=((Number)row.get("n")).intValue();else ecoTaken=((Number)row.get("n")).intValue();}if(f.economyCapacity()<ecoTaken||f.businessCapacity()<bizTaken)throw new IllegalArgumentException("Capacity cannot be below active ticket assignments.");if(ecoTaken+bizTaken>0&&(f.economyCapacity()!=((Number)current.get("economy_capacity")).intValue()||f.businessCapacity()!=((Number)current.get("business_capacity")).intValue()))throw new IllegalArgumentException("Cabin capacities cannot change after tickets are issued.");}
  int ea=f.economyCapacity()-ecoTaken,ba=f.businessCapacity()-bizTaken;Timestamp d=Timestamp.valueOf(dep),a=Timestamp.valueOf(arr);
  if(id==0)db.update("INSERT INTO flights(airline_id,flight_number,departure_city,destination_city,departure_time,arrival_time,available_seats,ticket_price,economy_capacity,economy_available_seats,economy_ticket_price,business_capacity,business_available_seats,business_ticket_price) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",f.airlineId(),f.flightNumber(),f.departureCity(),f.destinationCity(),d,a,ea+ba,f.economyPrice(),f.economyCapacity(),ea,f.economyPrice(),f.businessCapacity(),ba,f.businessPrice());
  else db.update("UPDATE flights SET airline_id=?,flight_number=?,departure_city=?,destination_city=?,departure_time=?,arrival_time=?,available_seats=?,ticket_price=?,economy_capacity=?,economy_available_seats=?,economy_ticket_price=?,business_capacity=?,business_available_seats=?,business_ticket_price=? WHERE flight_id=?",f.airlineId(),f.flightNumber(),f.departureCity(),f.destinationCity(),d,a,ea+ba,f.economyPrice(),f.economyCapacity(),ea,f.economyPrice(),f.businessCapacity(),ba,f.businessPrice(),id);
  return Map.of("message",id==0?"Flight added.":"Flight updated.");
 }
}
